// ── Google Maps ────────────────────────────────────────────────────────────
const GOOGLE_MAPS_API_KEY = (typeof import.meta !== "undefined" && import.meta.env?.VITE_GOOGLE_MAPS_KEY) || "";

function useGoogleMaps() {
  const [isLoaded, setIsLoaded] = useState(false);
  useEffect(() => {
    if (window.google && window.google.maps) { setIsLoaded(true); return; }
    if (document.querySelector('script[src*="maps.googleapis.com"]')) return;
    const script = document.createElement("script");
    script.src = `https://maps.googleapis.com/maps/api/js?key=${GOOGLE_MAPS_API_KEY}`;
    script.async = true; script.defer = true;
    script.onload = () => setIsLoaded(true);
    document.head.appendChild(script);
  }, []);
  return isLoaded;
}

function GoogleMapPanel({ events, selected, onSelect }) {
  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const markersRef = useRef([]);
  const infoWindowRef = useRef(null);
  const isLoaded = useGoogleMaps();

  const initMap = useCallback(() => {
    if (!mapRef.current || !window.google?.maps) return;
    const map = new window.google.maps.Map(mapRef.current, {
      center: { lat: 13.5, lng: 101.0 }, zoom: 6,
      styles: [
        { elementType: "geometry", stylers: [{ color: "#FAF6EF" }] },
        { elementType: "labels.text.stroke", stylers: [{ color: "#FAF6EF" }] },
        { elementType: "labels.text.fill", stylers: [{ color: "#5C3D22" }] },
        { featureType: "road", elementType: "geometry", stylers: [{ color: "#ffffff" }] },
        { featureType: "road", elementType: "geometry.stroke", stylers: [{ color: "#E8D8C4" }] },
        { featureType: "water", elementType: "geometry", stylers: [{ color: "#C8DFF0" }] },
        { featureType: "poi.park", elementType: "geometry", stylers: [{ color: "#D5DEC0" }] },
        { featureType: "transit", stylers: [{ visibility: "off" }] },
        { featureType: "poi", stylers: [{ visibility: "simplified" }] },
      ],
      mapTypeControl: false, streetViewControl: false, fullscreenControl: true,
    });
    mapInstanceRef.current = map;
    infoWindowRef.current = new window.google.maps.InfoWindow();
    markersRef.current = events.map((event) => {
      const marker = new window.google.maps.Marker({
        position: { lat: event.lat, lng: event.lng }, map, title: event.name,
        icon: { path: window.google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: "#C4522A", fillOpacity: 1, strokeColor: "#FFFDF9", strokeWeight: 2.5 },
      });
      marker.addListener("click", () => {
        onSelect(event);
        infoWindowRef.current.setContent(`<div style="font-family:'Bai Jamjuree','Poppins',sans-serif;padding:6px 4px;max-width:220px"><div style="font-weight:700;font-size:14px;color:#2C1A0E;margin-bottom:4px">${event.name}</div><div style="font-size:12px;color:#8C6840;">${event.location}</div></div>`);
        infoWindowRef.current.open(map, marker);
      });
      return { marker, eventId: event.id };
    });
  }, [events, onSelect]);

  useEffect(() => { if (isLoaded) initMap(); }, [isLoaded, initMap]);

  useEffect(() => {
    if (!window.google?.maps || !mapInstanceRef.current) return;
    markersRef.current.forEach(({ marker, eventId }) => {
      const isActive = selected?.id === eventId;
      marker.setIcon({ path: window.google.maps.SymbolPath.CIRCLE, scale: isActive ? 14 : 10, fillColor: isActive ? "#C4522A" : "#fff", fillOpacity: 1, strokeColor: isActive ? "#fff" : "#d35325", strokeWeight: isActive ? 3 : 2.5 });
      if (isActive) mapInstanceRef.current.panTo(marker.getPosition());
    });
  }, [selected]);

  return (
    <div className="mp-gmap-wrap">
      {!isLoaded && (
        <div className="mp-gmap-loading">
          <iconify-icon icon="mdi:map-outline" style={{ fontSize: 40, color: "#C4522A", marginBottom: 12 }}></iconify-icon>
          <p>กำลังโหลดแผนที่...</p>
          {!GOOGLE_MAPS_API_KEY && <p style={{ fontSize: 12, color: "#aaa", marginTop: 4 }}>⚠️ กรุณาตั้งค่า VITE_GOOGLE_MAPS_KEY</p>}
        </div>
      )}
      <div ref={mapRef} className="mp-gmap" style={{ display: isLoaded ? "block" : "none" }} />
    </div>
  );
}

// ── Custom Dropdown ──────────────────────────────────────────────────────────
function CustomDropdown({ value, onChange, options }) {
  const [open, setOpen] = useState(false);
  const [menuPos, setMenuPos] = useState({ top: 0, left: 0, width: 0 });
  const triggerRef = useRef(null);
  const menuRef = useRef(null);

  const updatePos = () => {
    if (!triggerRef.current) return;
    const r = triggerRef.current.getBoundingClientRect();
    setMenuPos({ top: r.bottom + 6, left: r.left, width: Math.max(r.width, 170) });
  };

  useEffect(() => {
    if (!open) return;
    const close = (e) => {
      if (triggerRef.current && !triggerRef.current.contains(e.target) && menuRef.current && !menuRef.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener("mousedown", close);
    window.addEventListener("scroll", () => setOpen(false), { passive: true });
    return () => { document.removeEventListener("mousedown", close); };
  }, [open]);

  const selected = options.find((o) => o.value === value);

  return (
    <div className="mp-dropdown">
      <button ref={triggerRef} type="button" className={`mp-dropdown__trigger${open ? " open" : ""}`}
        onClick={() => { updatePos(); setOpen((v) => !v); }}>
        <span className="mp-dropdown__val">{selected?.label}</span>
        <iconify-icon icon="mdi:chevron-down" className="mp-dropdown__chevron"></iconify-icon>
      </button>
      {open && createPortal(
        <div ref={menuRef} className="mp-dropdown__menu" style={{ top: menuPos.top, left: menuPos.left, minWidth: menuPos.width }}>
          {options.map((opt) => (
            <button key={opt.value} type="button"
              className={`mp-dropdown__item${opt.value === value ? " active" : ""}`}
              onClick={() => { onChange(opt.value); setOpen(false); }}>
              <span>{opt.label}</span>
              {opt.value === value && <iconify-icon icon="mdi:check" style={{ marginLeft: "auto", color: "#C4522A" }}></iconify-icon>}
            </button>
          ))}
        </div>,
        document.body
      )}
    </div>
  );
}

