// ── Featured Carousel (reference-style) ─────────────────────────────────────
function getUpcomingEvents(allEvents, count = 5) {
  // Take first N by id order (chronological in mock data)
  return [...allEvents].slice(0, count);
}

function FeaturedCarousel({ allEvents, onOpenModal }) {
  const items = getUpcomingEvents(allEvents, 5);
  const total = allEvents.length;
  const [current, setCurrent] = useState(0);
  const startXRef = useRef(null);

  const goTo = (idx) => {
    setCurrent(Math.max(0, Math.min(idx, items.length - 1)));
  };

  const handleTouchStart = (e) => { startXRef.current = e.touches[0].clientX; };
  const handleTouchEnd = (e) => {
    if (startXRef.current === null) return;
    const dx = e.changedTouches[0].clientX - startXRef.current;
    if (Math.abs(dx) > 40) dx < 0 ? goTo(current + 1) : goTo(current - 1);
    startXRef.current = null;
  };

  const ev = items[current];
  if (!ev) return null;
  const isMarket = ev.type === "ตลาดนัด";

  return (
    <div className="mp-fc-wrap">
      {/* Header */}
      <div className="mp-fc-header">
        <div className="mp-fc-header__left">
          <div className="mp-fc-header__bar" />
          <h2 className="mp-fc-header__title">อีเวนท์น่าสนใจ</h2>
        </div>
      </div>

      {/* Card — horizontal layout matching reference */}
      <div
        className="mp-fc-card"
        onClick={() => onOpenModal(ev)}
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
        key={ev.id}
      >
        {/* LEFT — orange/colored block */}
        <div className="mp-fc-card__left">
          <svg className="mp-fc-card__pattern" viewBox="0 0 180 180" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid slice">
            <circle cx="160" cy="20" r="90" fill="rgba(255,255,255,0.06)" />
            <circle cx="20" cy="160" r="60" fill="rgba(0,0,0,0.06)" />
          </svg>
          <span className={`mp-fc-badge ${isMarket ? "mp-fc-badge--market" : "mp-fc-badge--event"}`}>
            {ev.type}
          </span>
          <div className="mp-fc-card__cal-icon">
            <iconify-icon icon="mdi:calendar-month" style={{ fontSize: 44, color: "rgba(255,255,255,0.88)" }}></iconify-icon>
          </div>
          <div className="mp-fc-card__date">{ev.date}</div>
          <div className="mp-fc-card__time">{ev.time}</div>
        </div>

        {/* RIGHT — text content */}
        <div className="mp-fc-card__right">
          <div className="mp-fc-card__name">{ev.name}</div>
          <div className="mp-fc-card__location">
            <iconify-icon icon="mdi:map-marker-outline" style={{ fontSize: 13, color: "#C4522A", flexShrink: 0, marginTop: 1 }}></iconify-icon>
            <span>{ev.location}</span>
          </div>
          <div className="mp-fc-card__tags">
            {ev.tags.map((t) => <span key={t} className="mp-fc-tag">{t}</span>)}
          </div>
          <p className="mp-fc-card__desc">{ev.desc}</p>
          <div className="mp-fc-card__org">จัดโดย: <span>{ev.contact}</span></div>
        </div>

        {/* Arrow */}
        <div className="mp-fc-card__arrow">
          <iconify-icon icon="mdi:chevron-right" style={{ fontSize: 22, color: "#C4A882" }}></iconify-icon>
        </div>
      </div>

      {/* Dots */}
      <div className="mp-fc-dots">
        {items.map((_, i) => (
          <button
            key={i}
            className={`mp-fc-dot${i === current ? " active" : ""}`}
            onClick={(e) => { e.stopPropagation(); goTo(i); }}
            aria-label={`รายการที่ ${i + 1}`}
          />
        ))}
      </div>
    </div>
  );
}

