// ── Printer Section ───────────────────────────────────────────────────────────
const PROVINCE_OPTIONS_P = [
  { value: "all", label: "ทุกจังหวัด" },
  { value: "กรุงเทพมหานคร", label: "กรุงเทพมหานคร" },
  { value: "นครปฐม", label: "นครปฐม" },
  { value: "เพชรบุรี", label: "เพชรบุรี" },
];

function PrinterSection() {
  const [filterProvince, setFilterProvince] = useState("all");
  const [searchP, setSearchP] = useState("");
  const [modalPrinter, setModalPrinter] = useState(null);

  const filtered = PRINTERS.filter((p) => {
    const matchProv = filterProvince === "all" || p.province === filterProvince;
    const q = searchP.toLowerCase();
    const matchQ = !q || p.name.toLowerCase().includes(q) || p.province.toLowerCase().includes(q) || p.tags.some((t) => t.toLowerCase().includes(q));
    return matchProv && matchQ;
  });

  return (
    <div className="mp-printer-section">
      <div className="mp-printer-section__header">
        <div className="mp-printer-section__title-row">
          <div className="mp-fc-header__bar" />
          <h2 className="mp-fc-header__title">โรงพิมพ์ &amp; บรรจุภัณฑ์แนะนำ</h2>
        </div>
        <p className="mp-printer-section__sub">ค้นหาโรงพิมพ์และร้านบรรจุภัณฑ์ สำหรับผู้ประกอบการ OTOP และ SME</p>

        <div className="mp-printer-filters">
          <div className="mp-printer-search">
            <iconify-icon icon="mdi:magnify" style={{ fontSize: 16, color: "#8C6840" }}></iconify-icon>
            <input
              className="mp-printer-search__input"
              placeholder="ค้นหาโรงพิมพ์..."
              value={searchP}
              onChange={(e) => setSearchP(e.target.value)}
            />
          </div>
          <CustomDropdown value={filterProvince} onChange={setFilterProvince} options={PROVINCE_OPTIONS_P} />
        </div>
      </div>

      <div className="mp-event-list">
        {filtered.length === 0 ? (
          <div className="mp-empty">
            <iconify-icon icon="mdi:printer-off-outline" style={{ fontSize: 40, color: "#C4A882", marginBottom: 10 }}></iconify-icon>
            <p>ไม่พบโรงพิมพ์ที่ตรงกัน</p>
          </div>
        ) : (
          filtered.map((p) => (
            <PrinterCard key={p.id} printer={p} onOpenModal={setModalPrinter} />
          ))
        )}
      </div>

      {modalPrinter && <PrinterModal printer={modalPrinter} onClose={() => setModalPrinter(null)} />}
    </div>
  );
}

// ── Main Component ───────────────────────────────────────────────────────────
// Main section tabs: "events" | "printers"
const SECTION_TABS = [
  { value: "events",   label: "อีเวนท์ & ตลาดนัด", icon: "mdi:store-outline" },
  { value: "printers", label: "โรงพิมพ์ & บรรจุภัณฑ์", icon: "mdi:printer-outline" },
];

export default function MarketPlanning({ user }) {
  // ── section tab ──
  const [sectionTab, setSectionTab] = useState("events");

  // ── event filters ──
  const [search, setSearch] = useState("");
  const [activeType, setActiveType] = useState("all");
  const [filterMonth, setFilterMonth] = useState("all");
  const [filterRegion, setFilterRegion] = useState("all");
  const [sortBy, setSortBy] = useState("date");
  const [selected, setSelected] = useState(null);
  const [modalEvent, setModalEvent] = useState(null);
  const [showAll, setShowAll] = useState(false);
  const [userLocation, setUserLocation] = useState(null);
  const [locationLoading, setLocationLoading] = useState(false);
  const [locationError, setLocationError] = useState("");

  // ── printer filters ──
  const [filterProvince, setFilterProvince] = useState("all");
  const [searchP, setSearchP] = useState("");
  const [modalPrinter, setModalPrinter] = useState(null);

  const handleSelect = useCallback((event) => {
    setSelected((prev) => (prev?.id === event.id ? null : event));
  }, []);

  // Switch tab: reset show-all and search
  const handleSectionTab = (tab) => {
    setSectionTab(tab);
    setShowAll(false);
    setSearch("");
    // sync type filter when switching tabs
    if (tab === "printers") setActiveType("printer");
    else if (activeType === "printer") setActiveType("all");
  };

  // When type dropdown changes, auto-switch section tab
  const handleTypeChange = (val) => {
    setActiveType(val);
    if (val === "printer") {
      setSectionTab("printers");
      setShowAll(false);
    } else if (sectionTab === "printers") {
      setSectionTab("events");
      setShowAll(false);
    }
  };

  const requestUserLocation = useCallback(() => {
    if (userLocation) return;
    if (!navigator.geolocation) {
      setLocationError("เบราว์เซอร์ไม่รองรับ Geolocation");
      return;
    }
    setLocationLoading(true);
    setLocationError("");
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setUserLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        setLocationLoading(false);
      },
      () => {
        setLocationError("ไม่สามารถเข้าถึงตำแหน่งได้");
        setLocationLoading(false);
        setSortBy("date");
      },
      { enableHighAccuracy: false, timeout: 10000 }
    );
  }, [userLocation]);

  const handleSortChange = useCallback((val) => {
    setSortBy(val);
    if (val === "nearest") requestUserLocation();
  }, [requestUserLocation]);

  // ── filtered events ──
  const filtered = MOCK_EVENTS.filter((e) => {
    if (activeType === "printer") return false; // printer type → show nothing in events list
    const matchType = activeType === "all" || (activeType === "market" && e.type === "ตลาดนัด") || (activeType === "event" && e.type === "อีเวนท์");
    const matchMonth = filterMonth === "all" || getEventMonth(e.date) === filterMonth;
    const q = search.toLowerCase();
    const matchSearch = !q || e.name.toLowerCase().includes(q) || e.location.toLowerCase().includes(q) || e.tags.some((t) => t.toLowerCase().includes(q));
    return matchType && matchMonth && matchSearch;
  });
  const sorted = [...filtered].sort((a, b) => {
    if (sortBy === "name") return a.name.localeCompare(b.name, "th");
    if (sortBy === "nearest" && userLocation) {
      const distA = haversineKm(userLocation.lat, userLocation.lng, a.lat, a.lng);
      const distB = haversineKm(userLocation.lat, userLocation.lng, b.lat, b.lng);
      return distA - distB;
    }
    return a.id - b.id;
  });
  const displayed = showAll ? sorted : sorted.slice(0, 10);

  // ── filtered printers ── (uses main search bar; region maps to province)
  const filteredPrinters = PRINTERS.filter((p) => {
    const matchProv = filterProvince === "all" || p.province === filterProvince;
    const matchRegion = filterRegion === "all" || p.region === filterRegion;
    const q = (sectionTab === "printers" ? search : searchP).toLowerCase();
    const matchQ = !q || p.name.toLowerCase().includes(q) || p.province.toLowerCase().includes(q) || p.address.toLowerCase().includes(q) || p.tags.some((t) => t.toLowerCase().includes(q));
    return matchProv && matchRegion && matchQ;
  });

  return (
    <div className="mp-root">

      {/* ── Hero ── */}
      <div className="mp-hero">
        <div className="mp-hero__text">
          <h1 className="mp-hero__title">ค้นหาและเข้าร่วมกิจกรรม</h1>
          <p className="mp-hero__sub">อัปเดตงานและความรู้ดี ๆ จากทุกชุมชนทั่วไทย</p>
        </div>
      </div>

      {/* ── Search Bar ── */}
      <div className="mp-searchbar-wrap">
        <div className="mp-searchbar">
          <div className="mp-searchbar__field mp-searchbar__field--main">
            <iconify-icon icon="mdi:magnify" className="mp-searchbar__field-icon"></iconify-icon>
            <input
              className="mp-searchbar__input"
              placeholder={sectionTab === "printers" ? "ค้นหาโรงพิมพ์, จังหวัด, บรรจุภัณฑ์..." : "ค้นหางาน, สถานที่, คำสำคัญ..."}
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <div className="mp-searchbar__sep" />
          <div className="mp-searchbar__field mp-searchbar__field--sm">
            <div className="mp-searchbar__field-inner">
              <iconify-icon icon="mdi:tag-outline" className="mp-searchbar__field-icon-top"></iconify-icon>
              <span className="mp-searchbar__label">ประเภท</span>
            </div>
            <CustomDropdown value={activeType} onChange={handleTypeChange} options={TYPE_OPTIONS} />
          </div>
          <div className="mp-searchbar__sep" />
          <div className="mp-searchbar__field mp-searchbar__field--sm">
            <div className="mp-searchbar__field-inner">
              <iconify-icon icon="mdi:calendar-outline" className="mp-searchbar__field-icon-top"></iconify-icon>
              <span className="mp-searchbar__label">เดือน</span>
            </div>
            <CustomDropdown value={filterMonth} onChange={setFilterMonth} options={MONTH_OPTIONS} />
          </div>
          <div className="mp-searchbar__sep" />
          <div className="mp-searchbar__field mp-searchbar__field--sm">
            <div className="mp-searchbar__field-inner">
              <iconify-icon icon="mdi:map-marker-outline" className="mp-searchbar__field-icon-top"></iconify-icon>
              <span className="mp-searchbar__label">ภูมิภาค</span>
            </div>
            <CustomDropdown value={filterRegion} onChange={setFilterRegion} options={REGION_OPTIONS} />
          </div>
          <div className="mp-searchbar__sep" />
          <div className="mp-searchbar__field mp-searchbar__field--sm">
            <div className="mp-searchbar__field-inner">
              <iconify-icon icon="mdi:sort-ascending" className="mp-searchbar__field-icon-top"></iconify-icon>
              <span className="mp-searchbar__label">เรียงตาม</span>
            </div>
            <CustomDropdown value={sortBy} onChange={handleSortChange} options={SORT_OPTIONS} />
          </div>
          <button className="mp-searchbar__btn">
            <iconify-icon icon="mdi:magnify" style={{ fontSize: 17 }}></iconify-icon>
            ค้นหา
          </button>
        </div>
      </div>

      {/* ── Featured Carousel ── */}
      <div className="mp-fc-section" style={sectionTab === "printers" ? { minHeight: 0, paddingTop: 0 } : {}}>
        {sectionTab !== "printers" && (
          <FeaturedCarousel allEvents={sorted} onOpenModal={setModalEvent} />
        )}
      </div>

      {/* ── Main Layout ── */}
      <div className="mp-layout">

        {/* Left: List Column with tabs */}
        <div className="mp-list-col">

          {/* ── Section Tabs ── */}
          <div className="mp-section-tabs">
            {SECTION_TABS.map((tab) => (
              <button
                key={tab.value}
                className={`mp-section-tab${sectionTab === tab.value ? " active" : ""}`}
                onClick={() => handleSectionTab(tab.value)}
              >
                <iconify-icon icon={tab.icon} style={{ fontSize: 16 }}></iconify-icon>
                {tab.label}
                {tab.value === "events" && (
                  <span className="mp-section-tab__count">{sorted.length}</span>
                )}
                {tab.value === "printers" && (
                  <span className="mp-section-tab__count">{filteredPrinters.length}</span>
                )}
              </button>
            ))}
          </div>

          {/* ── Events Tab ── */}
          {sectionTab === "events" && (
            <>
              <div className="mp-result-header">
                <div className="mp-result-header__left">
                  <h2>ตลาดและงานอีเวนท์</h2>
                  <span className="mp-result-count">พบ <strong>{sorted.length}</strong> รายการ</span>
                </div>
              </div>

              {sortBy === "nearest" && locationLoading && (
                <div className="mp-location-status mp-location-status--loading">
                  <iconify-icon icon="mdi:loading" className="mp-spin"></iconify-icon>
                  กำลังค้นหาตำแหน่งของคุณ...
                </div>
              )}
              {sortBy === "nearest" && locationError && (
                <div className="mp-location-status mp-location-status--error">
                  <iconify-icon icon="mdi:alert-circle-outline"></iconify-icon>
                  {locationError}
                </div>
              )}
              {sortBy === "nearest" && userLocation && !locationLoading && (
                <div className="mp-location-status">
                  <iconify-icon icon="mdi:crosshairs-gps" style={{ color: "var(--terra)" }}></iconify-icon>
                  เรียงตามระยะทางจากตำแหน่งของคุณ
                </div>
              )}

              <div className="mp-event-list">
                {sorted.length === 0 ? (
                  <div className="mp-empty">
                    <iconify-icon icon="mdi:magnify-remove-outline" style={{ fontSize: 48, color: "#C4A882", marginBottom: 12 }}></iconify-icon>
                    <p>ไม่พบรายการที่ตรงกับการค้นหา</p>
                    <button className="mp-btn-outline" onClick={() => { setSearch(""); setActiveType("all"); setFilterMonth("all"); }}>ล้างตัวกรอง</button>
                  </div>
                ) : (
                  displayed.map((event) => (
                    <EventCard key={event.id} event={event}
                      isSelected={selected?.id === event.id}
                      onSelect={handleSelect}
                      onOpenModal={setModalEvent}
                      distance={sortBy === "nearest" && userLocation ? haversineKm(userLocation.lat, userLocation.lng, event.lat, event.lng) : null} />
                  ))
                )}
              </div>

              {sorted.length > 10 && (
                <div className="mp-load-more">
                  <button className="mp-btn-loadmore" onClick={() => setShowAll((v) => !v)}>
                    {showAll ? "แสดงน้อยลง" : "ดูเพิ่มเติม"}
                    <iconify-icon icon={showAll ? "mdi:chevron-up" : "mdi:chevron-down"} style={{ fontSize: 18 }}></iconify-icon>
                  </button>
                </div>
              )}
            </>
          )}

          {/* ── Printers Tab ── */}
          {sectionTab === "printers" && (
            <>
              <div className="mp-result-header">
                <div className="mp-result-header__left">
                  <h2>โรงพิมพ์ &amp; บรรจุภัณฑ์</h2>
                  <span className="mp-result-count">พบ <strong>{filteredPrinters.length}</strong> แห่ง</span>
                </div>
              </div>

              {/* Printer-specific filters */}
              <div className="mp-printer-filters" style={{ marginBottom: 14 }}>
                <CustomDropdown value={filterProvince} onChange={setFilterProvince} options={PROVINCE_OPTIONS_P} />
              </div>

              <div className="mp-event-list">
                {filteredPrinters.length === 0 ? (
                  <div className="mp-empty">
                    <iconify-icon icon="mdi:printer-off-outline" style={{ fontSize: 40, color: "#C4A882", marginBottom: 10 }}></iconify-icon>
                    <p>ไม่พบโรงพิมพ์ที่ตรงกัน</p>
                  </div>
                ) : (
                  filteredPrinters.map((p) => (
                    <PrinterCard key={p.id} printer={p} onOpenModal={setModalPrinter} />
                  ))
                )}
              </div>
            </>
          )}
        </div>

        {/* Right: Map */}
        <div className="mp-right-col" style={{ marginTop: sectionTab === "printers" ? 50 : -290 }}>
          <div className="mp-map-card">
            <div className="mp-map-header">
              <div className="mp-map-header__left">
                <div className="mp-map-header__icon">
                  <iconify-icon icon="mdi:map-outline" style={{ fontSize: 18, color: "#C4522A" }}></iconify-icon>
                </div>
                <div>
                  <div className="mp-map-header__title">
                    {sectionTab === "printers" ? "แผนที่โรงพิมพ์" : "แผนที่งานและตลาด"}
                  </div>
                  <div className="mp-map-header__sub">
                    {sectionTab === "printers" ? `${filteredPrinters.length} แห่งทั่วประเทศ` : "จาก OTOP ทั่วประเทศ"}
                  </div>
                </div>
              </div>
              <button className="mp-map-header__toggle">ดูทั้งหมด</button>
            </div>

            <GoogleMapPanel
              events={sectionTab === "printers" ? filteredPrinters : sorted}
              selected={selected}
              onSelect={handleSelect}
            />

            {selected && <MapDetailPanel event={selected} onClose={() => setSelected(null)} />}
          </div>
        </div>
      </div>

      {/* ── Footer Features ── */}
      <div className="mp-footer-features">
        <div className="mp-footer-features__inner">
          {[
            { icon: "mdi:account-group-outline", title: "เชื่อมต่อชุมชน", desc: "พบปะผู้ประกอบการและคนในชุมชน" },
            { icon: "mdi:chart-line", title: "เพิ่มโอกาสทางธุรกิจ", desc: "ขยายตลาด สร้างเครือข่าย และเติบโตได้ด้วยตัวเอง" },
            { icon: "mdi:sprout-outline", title: "สนับสนุนของท้องถิ่น", desc: "ร่วมกันพัฒนาชุมชนให้เข้มแข็งอย่างยั่งยืน" },
          ].map((f) => (
            <div key={f.title} className="mp-footer-feature">
              <div className="mp-footer-feature__icon">
                <iconify-icon icon={f.icon} style={{ fontSize: 26, color: "#C4522A" }}></iconify-icon>
              </div>
              <div>
                <div className="mp-footer-feature__title">{f.title}</div>
                <div className="mp-footer-feature__desc">{f.desc}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ── Modals ── */}
      {modalEvent && <EventModal event={modalEvent} onClose={() => setModalEvent(null)} />}
      {modalPrinter && <PrinterModal printer={modalPrinter} onClose={() => setModalPrinter(null)} />}
    </div>
  );
}